for y in range(0,len(tool),128):H[y:y+128]=np.interp(np.asarray(tool[y:y+128],dtype='f8')*gate['source_tool_metric_max_m'],table['tool_depth_m'],table['retained_displacement_m']).astype('f4')-base['mean_removed_retained_displacement_m']
