out={'scope':'Native-grid bilinear height convergence plus legacy roughness overlap audit; actual renderer basis is smooth triangles and remains a separate limit','intrinsic_roughness_retained':intrinsic,'source_roughness_range_in_coupon':[float(crop.min()),float(crop.max())],'source_roughness_mean_in_coupon':float(crop.mean()),'legacy_added_alpha_squared_range':[float(variance.min()),float(variance.max())],'native_bilinear_height_rms_error_m':float(np.sqrt(np.mean(d[sl]**2))),'native_bilinear_height_max_error_m':float(np.abs(d[sl]).max()),'maximum_height_displacement_pixels_at_current_view_upper_bound':float(np.abs(d[sl]).max()/(.028/960)),'native_bilinear_normal_rms_degrees':float(np.sqrt(np.mean(angle[sl]**2))),'native_bilinear_normal_max_degrees':float(angle[sl].max()),'model_defect':'Legacy broadening is fixed at sigma4 native texels, independent of actual mesh resolution, and therefore still counts the same resolved high-frequency relief after geometry refinement.','next_control':'Remove only the added source-height variance, retaining original intrinsic0.475 roughness and all geometry/state/other material coefficients. Explicit diagnostic control, not a calibrated BRDF result.','limits':['GGX has no finite untruncated slope second moment; the fourth-root variance rule is empirical, not an exact GGX variance composition.','The current native mesh uses smooth normals on triangles; this bilinear diagnostic does not prove exact renderer-normal agreement.','Unknown real subtexel polymer roughness is represented by the retained assumed intrinsic coefficient.'],'qualification':False};(R/'receipts/roughness_overlap_audit.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
